function s_length(x) { return [typeof x, x.length]; };
exports.s_length = s_length;
function s_index(x, y) { return x.indexOf(y); };
exports.s_index = s_index;
function s_scan(x) { let n = 0; for (let i = 0; i < x.length; i++) if (x[i] === "a" || x[i] === 1) n++; return n; };
exports.s_scan = s_scan;
function s_code(x) { return x.charCodeAt(0); };
exports.s_code = s_code;
function s_concat(x, y) { return x + y; };
exports.s_concat = s_concat;
function s_template(x) { return `<${x}>`; };
exports.s_template = s_template;
function s_equal(x, y) { return [x === y, x == y, x < y, Object.is(x, y)]; };
exports.s_equal = s_equal;
function s_slice(x) { return x.slice(1); };
exports.s_slice = s_slice;
function s_switch(x) { switch (x) { case "a": return 1; case "1": return 2; case 1: return 3; default: return 0; } };
exports.s_switch = s_switch;
function s_key(x) { return { a: "at a", 1: "at 1", null: "at null", undefined: "at undefined" }[x]; };
exports.s_key = s_key;
function s_truthy(x) { return x ? "yes" : "no"; };
exports.s_truthy = s_truthy;
function s_typeof(x) { return typeof x === "string" ? "a string" : typeof x; };
exports.s_typeof = s_typeof;
function s_spread(x) { return [...x]; };
exports.s_spread = s_spread;
function s_stored(x) { const held = { x }; held.x += "!"; return held; };
exports.s_stored = s_stored;
